// TypeScript Version: 4.1

/**
* Interface describing `dcross`.
*/
interface Routine {
	/**
	* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array.
	*
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param z - output array
	* @param strideZ - stride length for `z`
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	* var y = new Float64Array( [ 4.0, 5.0, 6.0 ] );
	* var z = new Float64Array( [ 0.0, 0.0, 0.0 ] );
	*
	* dcross( x, 1, y, 1, z, 1 );
	* // z => <Float64Array>[ -3.0, 6.0, -3.0 ]
	*/
	( x: Float64Array, strideX: number, y: Float64Array, strideY: number, z: Float64Array, strideZ: number ): Float64Array;

	/**
	* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array using alternative indexing semantics.
	*
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param offsetY - starting index for `y`
	* @param z - output array
	* @param strideZ - stride length for `z`
	* @param offsetZ - starting index for `z`
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	* var y = new Float64Array( [ 4.0, 5.0, 6.0 ] );
	* var z = new Float64Array( [ 0.0, 0.0, 0.0 ] );
	*
	* dcross.ndarray( x, 1, 0, y, 1, 0, z, 1, 0 );
	* // z => <Float64Array>[ -3.0, 6.0, -3.0 ]
	*/
	ndarray( x: Float64Array, strideX: number, offsetX: number, y: Float64Array, strideY: number, offsetY: number, z: Float64Array, strideZ: number, offsetZ: number ): Float64Array;
}

/**
* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array.
*
* @param x - first input array
* @param strideX - stride length for `x`
* @param y - second input array
* @param strideY - stride length for `y`
* @param z - output array
* @param strideZ - stride length for `z`
* @returns output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 4.0, 5.0, 6.0 ] );
* var z = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dcross( x, 1, y, 1, z, 1 );
* // z => <Float64Array>[ -3.0, 6.0, -3.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 4.0, 5.0, 6.0 ] );
* var z = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dcross.ndarray( x, 1, 0, y, 1, 0, z, 1, 0 );
* // z => <Float64Array>[ -3.0, 6.0, -3.0 ]
*/
declare var dcross: Routine;


// EXPORTS //

export = dcross;
